unsigned int fd = 3;
unsigned long offset_high = 0x1;
unsigned long offset_low = 0x80000000;
off_t new_offset;
unsigned int whence = 0; // SEEK_SET

// Reposition 64-bit file offset (high:low)
// Stores new offset in new_offset pointer.
int status = _llseek(
    fd,
    offset_high,
    offset_low,
    &new_offset,
    whence
);

// New position: new_offset (64-bit off_t)
// Status: 0 on success, -1 on failure
